const TITLE_MAP = {
  "chief executive officer":"CEO","chief operating officer":"COO","chief financial officer":"CFO",
  "chief information officer":"IT leadership","chief technology officer":"IT leadership",
  "vice president of operations":"VP Operations","vp of operations":"VP Operations",
  "vice president of finance":"VP Finance","vp of finance":"VP Finance",
  "vice president of revenue":"VP Revenue","vp of revenue":"VP Revenue"
};

function cleanName(n){ return String(n||"").replace(/\s+/g," ").trim(); }
function nameKey(n){
  return cleanName(n).toLowerCase()
    .replace(/[.,&]/g," ")
    .replace(/\b(inc|llc|ltd|lp|plc|corp|corporation|company|co)\b/g," ")
    .replace(/\s+/g," ").trim();
}
function normDomain(w){
  return String(w||"").toLowerCase().trim()
    .replace(/^https?:\/\//,"").replace(/^www\./,"").replace(/\/.*$/,"").replace(/\s/g,"");
}
function normDate(d){
  if(!d) return "";
  const t = new Date(d);
  return isNaN(t.getTime()) ? "" : t.toISOString().slice(0,10);
}
function normTitle(t){
  const raw = String(t||"").replace(/\s+/g," ").trim();
  const key = raw.toLowerCase();
  return TITLE_MAP[key] || raw;
}

const seen = {};
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const reasons = Array.isArray(j.review_reasons) ? j.review_reasons.slice() : [];
  const company_name = cleanName(j.company_name);
  const domain = normDomain(j.website);

  if (!company_name) reasons.push("MISSING_COMPANY_NAME");
  if (!domain) reasons.push("MISSING_WEBSITE");

  const key = domain || nameKey(company_name);
  if (!key) { continue; }

  const rec = {
    company_name: company_name || "UNKNOWN",
    company_key: key,
    website: domain ? ("https://" + domain) : "",
    domain: domain,
    industry: cleanName(j.industry) || "UNKNOWN",
    entity_type: String(j.entity_type||"").toLowerCase().trim() || "unknown",
    employee_count: Number(j.employee_count) || 0,
    property_count: Number(j.property_count) || 0,
    multi_brand: Boolean(j.multi_brand),
    multi_region: Boolean(j.multi_region),
    location: cleanName(j.location) || "UNKNOWN",
    current_product: j.current_product || "UNKNOWN / NOT PUBLIC",
    data_label: j.data_label || "UNLABELLED",
    evidence_label: j.evidence_label || "UNLABELLED",
    run_mode: j.run_mode,
    workflow_version: j.workflow_version,
    research_date: j.research_date || new Date().toISOString(),
    seed_signal: {
      title: cleanName(j.signal_title),
      url: String(j.signal_url||"").trim(),
      text: cleanName(j.signal_text),
      date: normDate(j.signal_date)
    },
    normalized_title_example: normTitle(j.decision_maker_title),
    status: reasons.length ? "REQUIRES_REVIEW" : "OK",
    review_reasons: reasons
  };

  if (seen[key] !== undefined) {
    const prev = out[seen[key]];
    prev.duplicate_merged = (prev.duplicate_merged || 0) + 1;
    if (rec.property_count > prev.property_count) prev.property_count = rec.property_count;
    if (rec.employee_count > prev.employee_count) prev.employee_count = rec.employee_count;
    continue;
  }
  seen[key] = out.length;
  out.push(rec);
}

if (!out.length) {
  return [{ json: { status:"REQUIRES_REVIEW", review_reasons:["NO_VALID_ACCOUNTS_AFTER_NORMALIZATION"] } }];
}
return out.map(function(o){ return { json:o }; });

const CONFIG = $('2. Load CONFIG').first().json.config;
const ICP = CONFIG.icp;

function bandPoints(value, table){
  for (const row of table) { if (Number(value) >= row[0]) return row[1]; }
  return 0;
}

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  const reasons = Array.isArray(j.review_reasons) ? j.review_reasons.slice() : [];
  const breakdown = [];

  const etPts = ICP.entity_type_points[j.entity_type] !== undefined ? ICP.entity_type_points[j.entity_type] : 0;
  breakdown.push({ rule:"entity_type", value:j.entity_type, points:etPts, max:10 });

  const pcPts = bandPoints(j.property_count, ICP.property_count_points);
  breakdown.push({ rule:"property_count", value:j.property_count, points:pcPts, max:7 });

  const ecPts = bandPoints(j.employee_count, ICP.employee_count_points);
  breakdown.push({ rule:"employee_count", value:j.employee_count, points:ecPts, max:4 });

  let cxPts = 0;
  if (j.multi_brand) cxPts += ICP.complexity_points.multi_brand;
  if (j.multi_region) cxPts += ICP.complexity_points.multi_region;
  breakdown.push({ rule:"portfolio_complexity", value:{multi_brand:j.multi_brand, multi_region:j.multi_region}, points:cxPts, max:4 });

  let icp_score = etPts + pcPts + ecPts + cxPts;
  if (icp_score > ICP.max_score) icp_score = ICP.max_score;

  if (!j.property_count) reasons.push("MISSING_PROPERTY_COUNT");
  if (j.entity_type === "unknown") reasons.push("UNKNOWN_ENTITY_TYPE");

  j.icp_score = Math.round(icp_score * 10) / 10;
  j.icp_breakdown = breakdown;
  j.icp_qualified = icp_score >= 10;
  j.icp_tier = icp_score >= 20 ? "CORE ICP" : (icp_score >= 14 ? "STRONG ICP" : (icp_score >= 10 ? "QUALIFIED" : "OUT OF ICP"));
  j.review_reasons = reasons;
  j.status = reasons.length ? "REQUIRES_REVIEW" : (j.status || "OK");
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;

return $input.all().map(function(item){
  const j = item.json;
  const s = j.seed_signal || {};
  const docs = [];
  if (s.title || s.text) {
    docs.push({
      title: s.title || "Untitled public item",
      url: s.url || "",
      date: s.date || "",
      text: s.text || "",
      source_type: "SIMULATED PRESS ITEM",
      evidence_label: "SIMULATED DATA"
    });
  }
  return { json: {
    company_key: j.company_key,
    documents: docs,
    research_source: "DEMO_BUNDLE",
    research_confidence: docs.length ? 0.7 : 0.1,
    research_note: "Demo research bundle. No live web request was made. Labelled SIMULATED DATA."
  }};
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const LIB = CONFIG.signal_library;
const base = $('5. ICP Scoring').all();
const research = $input.all();

function matchDocs(docs){
  const found = [];
  for (const doc of docs) {
    const hay = ((doc.title||"") + " " + (doc.text||"")).toLowerCase();
    if (!hay.trim()) continue;
    for (const sig of LIB) {
      const hits = sig.keywords.filter(function(k){ return hay.indexOf(String(k).toLowerCase()) !== -1; });
      if (!hits.length) continue;
      found.push({
        signal_name: sig.signal_name,
        signal_category: sig.signal_category,
        description: sig.description,
        why_it_matters: sig.why_it_matters,
        matched_keywords: hits,
        source_url: doc.url || "",
        source_title: doc.title || "",
        source_date: doc.date || "",
        source_type: doc.source_type || "PUBLIC WEB ITEM",
        evidence_label: doc.evidence_label || "PUBLIC FACT",
        evidence_text: String(doc.text||"").slice(0,400),
        extraction_confidence: Math.min(1, 0.5 + (0.12 * hits.length))
      });
    }
  }
  const seen = {};
  return found.filter(function(f){
    const k = f.signal_name + "|" + f.source_url;
    if (seen[k]) return false;
    seen[k] = true;
    return true;
  });
}

const out = [];
for (let i = 0; i < base.length; i++) {
  const acct = JSON.parse(JSON.stringify(base[i].json));
  const reasons = Array.isArray(acct.review_reasons) ? acct.review_reasons.slice() : [];
  const r = research[i] ? research[i].json : {};

  let docs = [];
  let researchConfidence = 0.5;
  let researchSource = "UNKNOWN";

  if (r && r.error) {
    reasons.push("RESEARCH_REQUEST_FAILED");
    researchConfidence = 0.1;
  } else {
    if (Array.isArray(r.documents)) docs = r.documents;
    else if (r.body && Array.isArray(r.body.documents)) docs = r.body.documents;
    else if (Array.isArray(r.results)) docs = r.results;
    researchSource = r.research_source || "LIVE_RESEARCH_ENDPOINT";
    researchConfidence = typeof r.research_confidence === "number" ? r.research_confidence : (docs.length ? 0.6 : 0.15);
  }

  if (!docs.length) reasons.push("NO_RESEARCH_DOCUMENTS");

  const raw = matchDocs(docs);
  if (!raw.length && docs.length) reasons.push("NO_SIGNAL_KEYWORDS_MATCHED");

  acct.research_source = researchSource;
  acct.research_confidence = researchConfidence;
  acct.documents_reviewed = docs.length;
  acct.raw_signals = raw;
  acct.review_reasons = reasons;
  acct.status = reasons.length ? "REQUIRES_REVIEW" : "OK";
  out.push({ json: acct });
}
return out;

const CONFIG = $('2. Load CONFIG').first().json.config;
const MAX_AGE = CONFIG.ignore_signals_older_than_days;
const today = new Date();

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  const reasons = Array.isArray(j.review_reasons) ? j.review_reasons.slice() : [];
  const valid = [];
  const rejected = [];

  for (const s of (j.raw_signals || [])) {
    const problems = [];
    if (!s.source_url || String(s.source_url).indexOf("http") !== 0) problems.push("NO_SOURCE_URL");
    if (!s.source_title) problems.push("NO_SOURCE_TITLE");
    if (!s.evidence_text || s.evidence_text.length < 25) problems.push("INSUFFICIENT_EVIDENCE_TEXT");

    const d = new Date(s.source_date);
    let age = null;
    if (!s.source_date || isNaN(d.getTime())) problems.push("NO_VALID_SOURCE_DATE");
    else {
      age = Math.floor((today.getTime() - d.getTime()) / 86400000);
      if (age < 0) problems.push("FUTURE_DATED_SOURCE");
      if (age > MAX_AGE) problems.push("SIGNAL_OLDER_THAN_MAX_AGE");
    }

    const copy = Object.assign({}, s, { age_days: age, validation_problems: problems });
    if (problems.length) rejected.push(copy); else valid.push(copy);
  }

  const seen = {};
  const deduped = valid.filter(function(s){
    const k = j.company_key + "|" + s.signal_name;
    if (seen[k]) return false;
    seen[k] = true;
    return true;
  });

  if (!deduped.length) reasons.push("NO_VALIDATED_SIGNALS");
  if (rejected.length) reasons.push("SOME_SIGNALS_REJECTED");

  j.signals_validated = deduped;
  j.signals_rejected = rejected;
  j.signal_count = deduped.length;
  j.review_reasons = reasons;
  j.status = deduped.length ? (j.status === "REQUIRES_REVIEW" ? "REQUIRES_REVIEW" : "OK") : "REQUIRES_REVIEW";
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const LIB = {};
CONFIG.signal_library.forEach(function(s){ LIB[s.signal_name] = s; });

function freshness(age){
  for (const b of CONFIG.freshness_bands) { if (age <= b.max_age_days) return b; }
  return CONFIG.freshness_bands[CONFIG.freshness_bands.length - 1];
}

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  const scored = (j.signals_validated || []).map(function(s){
    const meta = LIB[s.signal_name] || { signal_strength:1, scoring_weight:1, recommended_sales_play:"Re-engagement", recommended_persona:"VP Operations", freshness_requirement_days:180 };
    const band = freshness(s.age_days === null ? 99999 : s.age_days);
    const weighted = (meta.signal_strength / 5) * meta.scoring_weight * band.multiplier;
    return Object.assign({}, s, {
      signal_strength: meta.signal_strength,
      scoring_weight: meta.scoring_weight,
      recommended_sales_play: meta.recommended_sales_play,
      recommended_persona: meta.recommended_persona,
      freshness_requirement_days: meta.freshness_requirement_days,
      freshness_band: band.label,
      freshness_multiplier: band.multiplier,
      freshness_points: band.points,
      within_freshness_requirement: (s.age_days !== null && s.age_days <= meta.freshness_requirement_days),
      weighted_signal_score: Math.round(weighted * 100) / 100
    });
  }).sort(function(a,b){ return b.weighted_signal_score - a.weighted_signal_score; });

  j.signals_scored = scored;
  j.strongest_signal = scored.length ? scored[0].signal_name : "";
  j.strongest_signal_object = scored.length ? scored[0] : null;
  j.max_signal_strength = scored.length ? scored[0].signal_strength : 0;
  j.best_freshness_points = scored.length ? Math.max.apply(null, scored.map(function(s){ return s.freshness_points; })) : 0;
  j.best_freshness_band = scored.length ? scored[0].freshness_band : "NONE";
  j.signal_categories = scored.map(function(s){ return s.signal_category; }).filter(function(v,i,a){ return a.indexOf(v) === i; });
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  const names = (j.signals_scored || []).map(function(s){ return s.signal_name; });
  const fits = [];

  for (const p of CONFIG.products) {
    const matched = p.signal_map.filter(function(sn){ return names.indexOf(sn) !== -1; });
    if (!matched.length) continue;
    fits.push({
      label: "POTENTIAL PRODUCT FIT",
      product: p.product,
      capability: p.capability,
      matched_signals: matched,
      fit_basis: "Signal-to-capability mapping in CONFIG. This is an AI HYPOTHESIS, not a verified customer need."
    });
  }

  fits.sort(function(a,b){ return b.matched_signals.length - a.matched_signals.length; });
  j.potential_product_fit = fits;
  j.potential_actabl_fit = fits.map(function(f){ return f.product; });
  j.product_fit_count = fits.length;
  if (!fits.length && (j.signals_scored || []).length) {
    j.review_reasons = (j.review_reasons || []).concat(["NO_PRODUCT_FIT_MAPPED"]);
  }
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const PLAYS = {};
CONFIG.sales_plays.forEach(function(p){ PLAYS[p.play_name] = p; });

function limitWords(t, max){
  const w = String(t||"").trim().split(/\s+/).filter(Boolean);
  return w.length <= max ? w.join(" ") : w.slice(0, max).join(" ");
}

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  const top = j.strongest_signal_object;
  const fits = j.potential_actabl_fit || [];

  let persona = "VP Operations";
  let play = "Re-engagement";
  let problem = "No validated public signal was detected, so no business problem hypothesis is proposed.";
  let whyNow = "No validated public signal within the freshness window.";
  let evidence = [];
  let confidence = 0.2;

  if (top) {
    persona = CONFIG.persona_map[top.signal_name] || top.recommended_persona || "VP Operations";
    play = top.recommended_sales_play || "Operational Scaling";
    problem = "HYPOTHESIS: Public evidence suggests that " + (CONFIG.problem_map[top.signal_name] || "the observed change may create new operational or reporting requirements") + ".";
    whyNow = "FACT: " + top.source_title + " (" + top.source_date + ", " + top.evidence_label + "). HYPOTHESIS: the signal is " + top.age_days + " days old and falls in the " + top.freshness_band + " freshness band, so the operational question it raises is likely still open.";
    evidence = (j.signals_scored || []).map(function(s){
      return { source_url:s.source_url, source_title:s.source_title, source_date:s.source_date,
               evidence_text:s.evidence_text, signal_type:s.signal_name, evidence_label:s.evidence_label,
               confidence: s.extraction_confidence };
    });
    const evQuality = evidence.length ? (evidence.reduce(function(a,e){ return a + (e.confidence||0); },0) / evidence.length) : 0;
    confidence = Math.round(Math.min(0.95, (0.4*evQuality) + (0.3*(j.research_confidence||0)) + (0.3*(top.freshness_multiplier||0))) * 100) / 100;
  }

  const playDef = PLAYS[play] || PLAYS["Re-engagement"];
  const fitPhrase = fits.length ? fits.slice(0,2).join(" and ") : "Actabl capabilities";

  let angle = "";
  if (top) {
    angle = "Public item (" + top.source_date + "): " + limitWords(top.source_title, 16) + ". For operators at " +
      (j.property_count || "multiple") + " properties, " + (CONFIG.problem_map[top.signal_name] || "this often raises new reporting questions") +
      ". " + fitPhrase + " are used by hospitality operators for this. Worth a 15-minute look at how comparable portfolios handle it?";
    angle = limitWords(angle, CONFIG.outreach.max_words);
  } else {
    angle = "No validated public signal. No outreach recommended until a signal appears.";
  }

  const analysis = {
    company_name: j.company_name,
    company_website: j.website,
    icp_score: j.icp_score,
    signals: (j.signals_scored || []).map(function(s){ return s.signal_name; }),
    strongest_signal: j.strongest_signal || "",
    why_now: whyNow,
    business_problem_hypothesis: problem,
    potential_actabl_fit: fits,
    recommended_persona: persona,
    recommended_sales_play: play,
    personalization_angle: angle,
    recommended_next_action: playDef ? playDef.next_action : "Monitor only.",
    evidence: evidence,
    confidence: confidence
  };

  j.analysis = analysis;
  j.analysis_source = "RULE_BASED_BASELINE";
  j.ai_payload = {
    company_name: j.company_name, company_website: j.website, industry: j.industry,
    entity_type: j.entity_type, employee_count: j.employee_count, property_count: j.property_count,
    location: j.location, icp_score: j.icp_score, icp_breakdown: j.icp_breakdown,
    data_label: j.data_label,
    signals: (j.signals_scored || []).map(function(s){
      return { signal_name:s.signal_name, signal_category:s.signal_category, why_it_matters:s.why_it_matters,
               source_url:s.source_url, source_title:s.source_title, source_date:s.source_date,
               age_days:s.age_days, freshness_band:s.freshness_band, evidence_text:s.evidence_text,
               evidence_label:s.evidence_label };
    }),
    potential_product_fit: j.potential_product_fit,
    allowed_personas: CONFIG.personas,
    allowed_sales_plays: CONFIG.sales_plays.map(function(p){ return p.play_name; }),
    baseline_analysis: analysis
  };
  return { json: j };
});

const CONFIG = $('2. Load CONFIG').first().json.config;
const base = $('13. Deterministic Analyst').all();
const incoming = $input.all();
const PLAY_NAMES = CONFIG.sales_plays.map(function(p){ return p.play_name; });

function stripBanned(t){
  let s = String(t||"");
  CONFIG.outreach.banned_phrases.forEach(function(p){
    s = s.replace(new RegExp(p.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi"), "");
  });
  s = s.replace(/needs? Actabl/gi, "may be worth investigating for a potential Actabl fit");
  return s.replace(/\s+/g," ").replace(/^[\s,;.-]+/,"").trim();
}
function limitWords(t, max){
  const w = String(t||"").trim().split(/\s+/).filter(Boolean);
  return w.length <= max ? w.join(" ") : w.slice(0, max).join(" ");
}

const out = [];
for (let i = 0; i < base.length; i++) {
  const j = JSON.parse(JSON.stringify(base[i].json));
  const reasons = Array.isArray(j.review_reasons) ? j.review_reasons.slice() : [];
  const resp = incoming[i] ? incoming[i].json : {};
  let source = "RULE_BASED_BASELINE";
  const analysis = Object.assign({}, j.analysis);

  if (resp && resp.error) {
    reasons.push("AI_REQUEST_FAILED");
  } else if (resp && resp.choices && resp.choices[0] && resp.choices[0].message) {
    try {
      let raw = String(resp.choices[0].message.content || "").trim();
      raw = raw.replace(/^```json/i,"").replace(/^```/,"").replace(/```$/,"").trim();
      const parsed = JSON.parse(raw);
      const required = ["company_name","company_website","icp_score","signals","strongest_signal","why_now",
        "business_problem_hypothesis","potential_actabl_fit","recommended_persona","recommended_sales_play",
        "personalization_angle","recommended_next_action","evidence","confidence"];
      const missing = required.filter(function(k){ return parsed[k] === undefined; });
      if (missing.length) {
        reasons.push("AI_RESPONSE_MISSING_KEYS:" + missing.join(","));
      } else {
        if (typeof parsed.why_now === "string" && parsed.why_now.length > 10) analysis.why_now = stripBanned(parsed.why_now);
        if (typeof parsed.business_problem_hypothesis === "string" && parsed.business_problem_hypothesis.length > 10) analysis.business_problem_hypothesis = stripBanned(parsed.business_problem_hypothesis);
        if (typeof parsed.personalization_angle === "string" && parsed.personalization_angle.length > 10) analysis.personalization_angle = limitWords(stripBanned(parsed.personalization_angle), CONFIG.outreach.max_words);
        if (typeof parsed.recommended_next_action === "string" && parsed.recommended_next_action.length > 5) analysis.recommended_next_action = stripBanned(parsed.recommended_next_action);
        if (CONFIG.personas.indexOf(parsed.recommended_persona) !== -1) analysis.recommended_persona = parsed.recommended_persona;
        else reasons.push("AI_PERSONA_OUT_OF_LIST");
        if (PLAY_NAMES.indexOf(parsed.recommended_sales_play) !== -1) analysis.recommended_sales_play = parsed.recommended_sales_play;
        else reasons.push("AI_PLAY_OUT_OF_LIST");
        if (Array.isArray(parsed.potential_actabl_fit)) {
          const allowed = parsed.potential_actabl_fit.filter(function(p){ return (j.potential_actabl_fit||[]).indexOf(p) !== -1; });
          if (allowed.length) analysis.potential_actabl_fit = allowed;
        }
        if (typeof parsed.confidence === "number" && parsed.confidence >= 0 && parsed.confidence <= 1) analysis.confidence = parsed.confidence;
        source = "LLM_VALIDATED";
      }
    } catch (e) {
      reasons.push("AI_RESPONSE_MALFORMED");
    }
  }

  analysis.company_name = j.company_name;
  analysis.company_website = j.website;
  analysis.icp_score = j.icp_score;
  analysis.evidence = j.analysis.evidence;

  j.analysis = analysis;
  j.analysis_source = source;
  j.review_reasons = reasons;
  if (reasons.length && j.status !== "REQUIRES_REVIEW") j.status = "REQUIRES_REVIEW";
  out.push({ json: j });
}
return out;

const CONFIG = $('2. Load CONFIG').first().json.config;
const W = CONFIG.scoring_weights;
const EXPANSION_SIGNALS = ["ACQUISITION","PORTFOLIO_EXPANSION","NEW_PROPERTY_OPENING","RAPID_GROWTH","OPERATIONAL_EXPANSION"];

function r1(n){ return Math.round(n * 10) / 10; }

return $input.all().map(function(item){
  const j = JSON.parse(JSON.stringify(item.json));
  const scored = j.signals_scored || [];
  const b = {};

  b.icp_fit = r1(Math.min(W.icp_fit, j.icp_score || 0));

  const maxStrength = scored.length ? Math.max.apply(null, scored.map(function(s){ return s.signal_strength; })) : 0;
  const multiBonus = Math.min(3, Math.max(0, (scored.length - 1) * 1.5));
  b.signal_strength = r1(Math.min(W.signal_strength, ((maxStrength / 5) * 17) + multiBonus));

  b.signal_freshness = r1(Math.min(W.signal_freshness, j.best_freshness_points || 0));

  const nFit = j.product_fit_count || 0;
  const fitTable = [0, 6, 9, 12, 15];
  b.product_fit = r1(fitTable[Math.min(nFit, 4)]);

  let expansion = 0;
  const pc = j.property_count || 0;
  if (pc >= 50) expansion += 6; else if (pc >= 20) expansion += 5; else if (pc >= 10) expansion += 4; else if (pc >= 5) expansion += 3; else if (pc >= 2) expansion += 1;
  const hasExp = scored.some(function(s){ return EXPANSION_SIGNALS.indexOf(s.signal_name) !== -1; });
  if (hasExp) expansion += 4;
  b.expansion_potential = r1(Math.min(W.expansion_potential, expansion));

  const personaDerived = j.analysis && j.analysis.recommended_persona && j.strongest_signal &&
    CONFIG.persona_map[j.strongest_signal] !== undefined;
  b.persona_relevance = personaDerived ? W.persona_relevance : 2;

  const ev = (j.analysis && j.analysis.evidence) || [];
  let evQ = 0;
  if (ev.length) {
    evQ = ev.reduce(function(a, e){
      let q = 0;
      if (e.source_url) q += 0.4;
      if (e.source_date) q += 0.3;
      if (e.evidence_text && e.evidence_text.length >= 60) q += 0.3;
      return a + q;
    }, 0) / ev.length;
  }
  b.evidence_quality = r1(W.evidence_quality * evQ);

  const conf = (j.analysis && typeof j.analysis.confidence === "number") ? j.analysis.confidence : 0;
  b.research_confidence = r1(W.research_confidence * conf);

  const total = Object.keys(b).reduce(function(a, k){ return a + b[k]; }, 0);
  const score = Math.round(Math.max(0, Math.min(100, total)));

  let priority = "LOW PRIORITY";
  for (const band of CONFIG.priority_bands) { if (score >= band.min) { priority = band.label; break; } }

  j.opportunity_score = score;
  j.opportunity_score_breakdown = b;
  j.opportunity_score_formula = "icp_fit(25) + signal_strength(20) + signal_freshness(15) + product_fit(15) + expansion_potential(10) + persona_relevance(5) + evidence_quality(5) + research_confidence(5)";
  j.priority = priority;
  j.priority_note = CONFIG.priority_note;
  return { json: j };
});

