const CONFIG = $('2. Load CONFIG').first().json.config;
const MAX = CONFIG.outreach.max_words;

function words(t){ return String(t||"").trim().split(/\s+/).filter(Boolean); }
function limitWords(t, max){ const w = words(t); return w.length <= max ? w.join(" ") : w.slice(0, max).join(" "); }
function clean(t){
  let s = String(t||"");
  CONFIG.outreach.banned_phrases.forEach(function(p){
    s = s.replace(new RegExp(p.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "gi"), "");
  });
  s = s.replace(/needs? Actabl/gi, "may be worth investigating for a potential Actabl fit");
  return s.replace(/\s{2,}/g," ").replace(/^[\s,;.-]+/,"").trim();
}

